                    <button onClick={() => handleResetPlayerSlot(type)} className="p-1 hover:bg-white/10 rounded transition-colors text-gray-400 hover:text-white" title="Reset Slot"><RefreshCw className="w-3 h-3" /></button>
                </div>
            );
        }
        return (
